CREATE TABLE remote_media_sources (id VARCHAR(36) PRIMARY KEY, media_item_id VARCHAR(36), episode_id VARCHAR(36), remote_source_id VARCHAR(36) NOT NULL, provider_type VARCHAR(16) NOT NULL, external_key VARCHAR(128) NOT NULL, stream_ref TEXT NOT NULL, stream_sealed BOOLEAN NOT NULL DEFAULT FALSE, quality_hint VARCHAR(32), is_active BOOLEAN NOT NULL DEFAULT TRUE, last_seen_at VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_remote_media_source_key(remote_source_id, external_key), INDEX idx_remote_media_item(media_item_id), INDEX idx_remote_media_episode(episode_id), FOREIGN KEY(media_item_id) REFERENCES media_items(id) ON DELETE CASCADE, FOREIGN KEY(episode_id) REFERENCES tv_episodes(id) ON DELETE CASCADE, FOREIGN KEY(remote_source_id) REFERENCES remote_sources(id) ON DELETE CASCADE) ENGINE=InnoDB;
ALTER TABLE media_files ADD COLUMN storage_kind VARCHAR(16) NOT NULL DEFAULT 'LOCAL', ADD COLUMN remote_media_source_id VARCHAR(36);
